<?php require 'includes/conexao.php'; require 'includes/verificar_login.php'; exigir_login(); $stmt=$pdo->prepare('SELECT c.*,uc.conquistada_em FROM conquistas c LEFT JOIN usuario_conquistas uc ON uc.conquista_id=c.id AND uc.usuario_id=? ORDER BY uc.conquistada_em DESC,c.id'); $stmt->execute([$_SESSION['usuario_id']]); $lista=$stmt->fetchAll(); $titulo='Conquistas'; $home='dashboard.php'; include 'includes/header.php'; ?><div class="section-heading"><div><div class="eyebrow">Colecione todas</div><h1 style="font-size:4rem">Conquistas</h1><p>Cada medalha registra uma vitória sua.</p></div></div><div class="game-grid"><?php foreach($lista as $c): ?><article class="card medal" style="opacity:<?= $c['conquistada_em'] ? '1' : '.5' ?>"><div class="medal-icon"><?= $c['icone'] ?></div><div><h3><?= htmlspecialchars($c['nome']) ?></h3><p><?= htmlspecialchars($c['descricao']) ?></p><?php if($c['conquistada_em']): ?><span class="tag">Conquistada</span><?php else: ?><span class="tag">Em busca</span><?php endif; ?></div></article><?php endforeach; ?></div><?php include 'includes/footer.php'; ?>
